<?php
require_once __DIR__.'/../config/bootstrap.php'; require_role('administrador');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$uid=(int)($_POST['unidad_id']??0);$teacher=(int)($_POST['docente_id']??0);$date=$_POST['fecha_clase']??'';$type=$_POST['tipo']??'';$hours=(int)($_POST['horas']??24);if($uid&&$teacher&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)&&in_array($type,['asistencia','notas'],true)&&$hours>=1&&$hours<=168){$open=new DateTimeImmutable('now');$due=$open->modify("+{$hours} hours");$s=$pdo->prepare('INSERT INTO plazos_registro(unidad_id,docente_id,fecha_clase,tipo,abierto_en,vencimiento,estado,abierto_por) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$uid,$teacher,$date,$type,$open->format('Y-m-d H:i:s'),$due->format('Y-m-d H:i:s'),'abierto',(int)current_user()['id']]);$assign=$pdo->prepare('INSERT IGNORE INTO asignaciones_docentes(docente_id,unidad_id,asignada_por) VALUES(?,?,?)');$assign->execute([$teacher,$uid,(int)current_user()['id']]);audit($pdo,(int)current_user()['id'],'crear_plazo',"{$type}; unidad {$uid}; vence ".$due->format('Y-m-d H:i:s'));flash('success','Plazo creado.');}else flash('error','Verifica los datos.');redirect('plazos.php');}
$units=$pdo->query('SELECT id,nombre FROM unidades_didacticas ORDER BY nombre')->fetchAll();$teachers=$pdo->query("SELECT id,nombres,apellidos FROM usuarios WHERE rol='docente' AND estado='activo' ORDER BY apellidos")->fetchAll();$rows=$pdo->query('SELECT p.*,u.nombre unidad,us.nombres,us.apellidos FROM plazos_registro p JOIN unidades_didacticas u ON u.id=p.unidad_id JOIN usuarios us ON us.id=p.docente_id ORDER BY p.vencimiento DESC')->fetchAll();
$pageTitle='Plazos';$assetPrefix='../';require __DIR__.'/../includes/header.php';?>
<div class="dashboard-head"><div><div class="eyebrow">CONTROL DE PLAZOS</div><h1>Plazos de registro</h1><p class="muted">El valor predeterminado es 24 horas; cualquier extensión debe ser autorizada.</p></div><a class="btn secondary" href="index.php">Volver</a></div>
<section class="panel"><h2>Abrir plazo</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><div class="field"><label>Unidad</label><select name="unidad_id" required><?php foreach($units as $u):?><option value="<?= (int)$u['id']?>"><?= h($u['nombre'])?></option><?php endforeach;?></select></div><div class="field"><label>Docente</label><select name="docente_id" required><?php foreach($teachers as $t):?><option value="<?= (int)$t['id']?>"><?= h($t['apellidos'].', '.$t['nombres'])?></option><?php endforeach;?></select></div><div class="field"><label>Fecha de clase</label><input type="date" name="fecha_clase" required></div><div class="field"><label>Tipo</label><select name="tipo"><option value="asistencia">Asistencia</option><option value="notas">Notas</option></select></div><div class="field"><label>Duración (horas)</label><input type="number" name="horas" min="1" max="168" value="24" required></div><div class="field full"><button class="btn primary">Abrir plazo</button></div></form></section>
<section class="panel"><h2>Plazos creados</h2><div class="table-wrap"><table><thead><tr><th>Tipo</th><th>Unidad</th><th>Docente</th><th>Clase</th><th>Vencimiento</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):$expired=strtotime($r['vencimiento'])<time();?><tr><td><?= h($r['tipo'])?></td><td><?= h($r['unidad'])?></td><td><?= h($r['nombres'].' '.$r['apellidos'])?></td><td><?= h($r['fecha_clase'])?></td><td><?= h($r['vencimiento'])?></td><td><span class="status <?= $expired?'danger':'success'?>"><?= $expired?'Vencido':h($r['estado'])?></span></td></tr><?php endforeach;?></tbody></table></div></section>
